DIALOGS = [
[anyone,"gm_intro", [(eq,"$g_talk_troop", "trp_boar_clan_guild_master"),],
   "I am Warlord Akeem Olaju.  One of a handful that roam the barren lands of the Sarranid Sultanate.  Seek me out if you wish to hire my men.  However, our organization is loose and many of the men in my clan lead their own warbands and patrol the outskirts of our realm in search of scum who feed on the weak and ignorant.  Sure, we are mercenaries, everyone has to eat to live.  But not I, nor any of the Boar Clan war parties you encounter in your travels, will fight for a dishonorable cause.  Any other questions?", "gm_talk",[]],
]
